{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg","align":"stretch"},"children":["composer","waits-note","returns-note"]}}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Plan the trip","lede":"A day-by-day plan that fits your budget and pace.","runLabel":"Plan my trip","columns":"2"},"on":{"press":[{"action":"validateForm"},{"action":"run"}]},"children":["trip-group","budget-group","travellers-group","good-group"]}}
{"op":"add","path":"/elements/trip-group","value":{"type":"FieldGroup","props":{"title":"The trip"},"children":["title-input","city-input","country-segmented","stay-dates","must-see-chips"]}}
{"op":"add","path":"/elements/title-input","value":{"type":"Input","props":{"label":"Title","name":"title","type":"text","value":{"$bindState":"/inputs/request/title"},"checks":[{"type":"required","message":"A title is needed"}]}},"children":[]}
{"op":"add","path":"/elements/city-input","value":{"type":"Input","props":{"label":"City","name":"city","type":"text","value":{"$bindState":"/inputs/request/stay/city"},"checks":[{"type":"required","message":"A city is needed"}]}},"children":[]}
{"op":"add","path":"/elements/country-segmented","value":{"type":"Segmented","props":{"label":"Country","name":"country","options":["France","Italy","Japan","Portugal","Spain","United States"],"value":{"$bindState":"/inputs/request/stay/country"}}},"children":[]}
{"op":"add","path":"/elements/stay-dates","value":{"type":"DateRange","props":{"label":"Dates","from":{"$bindState":"/inputs/request/stay/arriving_on"},"to":{"$bindState":"/inputs/request/stay/leaving_on"}}},"children":[]}
{"op":"add","path":"/elements/must-see-chips","value":{"type":"Chips","props":{"label":"Must-see","placeholder":"Add a place","value":{"$bindState":"/inputs/request/stay/must_see"}}},"children":[]}
{"op":"add","path":"/elements/budget-group","value":{"type":"FieldGroup","props":{"title":"Budget & style"},"children":["budget-input","currency-segmented","pace-segmented","style-segmented"]}}
{"op":"add","path":"/elements/budget-input","value":{"type":"NumberInput","props":{"label":"Budget","value":{"$bindState":"/inputs/request/budget"}}},"children":[]}
{"op":"add","path":"/elements/currency-segmented","value":{"type":"Segmented","props":{"label":"Currency","name":"currency","options":["EUR","USD","GBP","JPY"],"value":{"$bindState":"/inputs/request/currency"}}},"children":[]}
{"op":"add","path":"/elements/pace-segmented","value":{"type":"Segmented","props":{"label":"Pace","name":"pace","options":["slow","balanced","packed"],"value":{"$bindState":"/inputs/request/pace"}}},"children":[]}
{"op":"add","path":"/elements/style-segmented","value":{"type":"Segmented","props":{"label":"Style","name":"style","options":["culture","food","nature","nightlife","family"],"value":{"$bindState":"/inputs/request/style"}}},"children":[]}
{"op":"add","path":"/elements/travellers-group","value":{"type":"FieldGroup","props":{"title":"Who's going"},"children":["travellers-list"]}}
{"op":"add","path":"/elements/travellers-list","value":{"type":"CompactList","props":{"label":"Travellers","items":{"$bindState":"/inputs/request/travellers"},"primary":"name","secondary":["age","dietary"],"addLabel":"Add traveller"}},"children":[]}
{"op":"add","path":"/elements/good-group","value":{"type":"FieldGroup","props":{"title":"Good to know"},"children":["with-children-switch","accessibility-input","notes-textarea","inspiration-field"]}}
{"op":"add","path":"/elements/with-children-switch","value":{"type":"Switch","props":{"label":"Travelling with children","name":"with_children","checked":{"$bindState":"/inputs/request/with_children"}}},"children":[]}
{"op":"add","path":"/elements/accessibility-input","value":{"type":"Input","props":{"label":"Accessibility needs","name":"accessibility","type":"text","value":{"$bindState":"/inputs/request/accessibility"}}},"children":[]}
{"op":"add","path":"/elements/notes-textarea","value":{"type":"Textarea","props":{"label":"Notes","name":"notes","rows":3,"value":{"$bindState":"/inputs/request/notes"}}},"children":[]}
{"op":"add","path":"/elements/inspiration-field","value":{"type":"MthdsField","props":{"path":"/inputs/inspiration"}},"children":[]}
{"op":"add","path":"/elements/waits-note","value":{"type":"Text","props":{"text":"Runs once the trip request is complete.","variant":"caption"}},"children":[]}
{"op":"add","path":"/elements/returns-note","value":{"type":"Text","props":{"text":"You'll get an overview, the days laid out, costs by category, an estimated total and practical notes.","variant":"muted"}},"children":[]}
